contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: caller chooses an amount to forward to c
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough Ether to forward
        require(address(this).balance >= amount);

        // observe before state
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        uint bal_before = address(c).balance;

        // perform the state-changing call and detect revert
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint bal_after = address(c).balance;

        // General rule:
        // - If amount != TICKET_AMOUNT then the call must revert and there is no observable change to pot or contract balance.
        // - If amount == TICKET_AMOUNT and the call does not revert then pot_after is either pot_before + amount or 0.
        // We express TICKET_AMOUNT by the known constant 10 and require the assertion to reflect observable values.
        assert(
            // When amount is not the ticket price, the call must revert and nothing changes
            (amount != 10 && reverted && pot_after == pot_before && bal_after == bal_before)
            ||
            // When amount is the ticket price, if it reverts then nothing changed; if it succeeds then pot is either increased by amount or reset to 0
            (amount == 10 && (
                (reverted && pot_after == pot_before && bal_after == bal_before)
                || (!reverted && (pot_after == pot_before + amount || pot_after == 0))
            ))
        );
    }

    // accept Ether when C pays out to this contract
    receive() external payable {}
}

